import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0]); m = int(data[1])
    adj = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        u = int(data[p]); v = int(data[p + 1]); p += 2
        adj[u].append(v); adj[v].append(u)
    nb = [set(a) for a in adj]
    res = []
    for u in range(n):
        cnt = {}
        for w in adj[u]:
            for x in adj[w]:
                if x != u:
                    cnt[x] = cnt.get(x, 0) + 1
        best, bi = 0, -1
        su = nb[u]
        for x, c in cnt.items():
            if x in su:
                continue
            if c > best or (c == best and x < bi):
                best, bi = c, x
        res.append(bi)
    print(' '.join(map(str, res)))

